css:
#loader-30 {
  display: inline-grid;
  width: 40px;
  aspect-ratio: 1;
  border-radius: 50%;
  background: repeating-conic-gradient(from 30deg,#C02942 0 60deg,#0B486B 0 120deg);
  animation: l10-0 2s linear infinite;
}
#loader-30:before,
#loader-30:after {
  content: '';
  grid-area: 1/1;
  border-radius: 50%;
  background: inherit;
  transform: rotate(0turn) translate(100%,0);
  animation: l10-1 3s infinite ease-in-out;
}
#loader-30:after {
  animation-delay: -1.5s;
}
@keyframes l10-0 {
  to{rotate: -1turn}
}
@keyframes l10-1 {
  to{transform: rotate(1turn) translate(100%,0) rotate(1turn)}
}
